<?php $isCategory=$kind==='categories'; $label=$isCategory?'Catégories':'Titres'; ?><div class="admin-heading"><div><p class="eyebrow">ORGANISER LES ARCHIVES</p><h1><?= $label ?><span>.</span></h1><p class="admin-intro"><?= $isCategory?'Une catégorie utilisée ne peut être archivée ni supprimée.':'Un titre peut récompenser plusieurs succès. Les associations se gèrent dans les fiches des succès.' ?></p></div></div><section class="admin-panel neu-flat"><h2><?= $isCategory?'Nouvelle catégorie':'Nouveau titre' ?></h2><form method="post" action="/admin/<?= $kind ?>" class="admin-form"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="action" value="save"><div class="form-grid"><label>Nom<input name="name" maxlength="<?= $isCategory?100:191 ?>" required></label><label>Slug unique<input name="slug" maxlength="191" pattern="[a-z0-9]+(-[a-z0-9]+)*" required></label></div><?php if ($isCategory): ?><label>Couleur<input type="color" name="color" value="#65C66B" required></label><?php endif; ?><label>Description<textarea name="description" rows="2" maxlength="12000"></textarea></label><button class="primary-button">Créer</button></form></section>
<div class="taxonomy-grid"><?php foreach ($records as $record): ?><section class="admin-panel neu-flat"><div class="panel-heading"><h2><?= e($record['name']) ?></h2><span class="admin-badge"><?= $record['uses_count'] ?> succès<?= !empty($record['archived_at'])?' · Archivée':'' ?></span></div><details><summary>Modifier</summary><form method="post" action="/admin/<?= $kind ?>" class="admin-form"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= $record['id'] ?>"><input type="hidden" name="action" value="save"><label>Nom<input name="name" maxlength="<?= $isCategory?100:191 ?>" required value="<?= e($record['name']) ?>"></label><?php if ($isCategory): ?><label>Couleur<input type="color" name="color" required value="<?= e($record['color']) ?>"></label><?php endif; ?><label>Description<textarea name="description" rows="3" maxlength="12000"><?= e($record['description']) ?></textarea></label><button class="secondary-button">Enregistrer</button></form></details><?php if ($isCategory || App\Services\PermissionService::owner($user)): ?><details><summary>Cycle de vie</summary><form method="post" action="/admin/<?= $kind ?>" class="admin-form"><input type="hidden" name="csrf" value="<?= e($csrf) ?>"><input type="hidden" name="id" value="<?= $record['id'] ?>"><label>Action<select name="action"><?php if ($isCategory): ?><option value="<?= $record['archived_at']?'restore':'archive' ?>"><?= $record['archived_at']?'Restaurer':'Archiver' ?></option><?php endif; ?><?php if (App\Services\PermissionService::owner($user)): ?><option value="delete">Supprimer définitivement</option><?php endif; ?></select></label><label class="check-label"><input type="checkbox" name="confirm" value="1" required>Je confirme cette opération</label><button class="secondary-button danger-button">Appliquer</button></form></details><?php endif; ?></section><?php endforeach; ?></div>
